package sohal.lld.zerodha.state;import sohal.lld.zerodha.enums.OrderStatus;import sohal.lld.zerodha.order.Order;public class OpenState implements OrderState {    @Override    public void handleOrder(Order order) {        System.out.println("Order is open and wating for execution");    }    @Override    public void cancelOrder(Order order) {        order.setStatus(OrderStatus.CANCELED);        order.setState(new CancelledState());        System.out.printf("Order %s has been cancelled\n", order.getOrderId());    }}